/* Boowie service worker — generated by scripts/generate-sw-manifest.mjs. Do not edit out/sw.js by hand. */
const VERSION = "__BUILD_VERSION__";
const PRECACHE = __PRECACHE__;
const CACHE = `titan-${VERSION}`;
const RUNTIME = "titan-runtime";
// "" at a domain root, "/Boovie" on GitHub Pages project sites.
const BASE = new URL(self.registration.scope).pathname.replace(/\/$/, "");
const SHELLS = ["/", "/store/", "/book/", "/settings/"].map((p) => BASE + p);

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      // Add individually so one missing file does not abort the whole install.
      await Promise.all(PRECACHE.map((url) => cache.add(new Request(url, { cache: "reload" })).catch(() => undefined)));
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.filter((k) => k.startsWith("titan-") && k !== CACHE && k !== RUNTIME).map((k) => caches.delete(k)));
      await self.clients.claim();
    })(),
  );
});

function shellFor(url) {
  const path = url.pathname.endsWith("/") ? url.pathname : `${url.pathname}/`;
  return SHELLS.includes(path) ? path : `${BASE}/`;
}

async function networkFirst(request, url) {
  try {
    const res = await Promise.race([
      fetch(request),
      new Promise((_, reject) => setTimeout(() => reject(new Error("timeout")), 4000)),
    ]);
    if (res.ok) {
      const cache = await caches.open(CACHE);
      void cache.put(shellFor(url), res.clone());
    }
    return res;
  } catch {
    return (await caches.match(shellFor(url))) || (await caches.match(`${BASE}/`)) || Response.error();
  }
}

async function cacheFirst(request) {
  const hit = await caches.match(request);
  if (hit) return hit;
  const res = await fetch(request);
  if (res.ok) void (await caches.open(RUNTIME)).put(request, res.clone());
  return res;
}

async function staleWhileRevalidate(request) {
  const cached = (await caches.match(request)) || (await caches.match(request, { ignoreSearch: true }));
  const refresh = fetch(request)
    .then(async (res) => {
      if (res.ok && res.type === "basic") (await caches.open(RUNTIME)).put(request, res.clone());
      return res;
    })
    .catch(() => undefined);
  return cached || (await refresh) || Response.error();
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  // Book and audio files are downloaded into IndexedDB/OPFS by the app; stream previews need Range requests.
  if (url.pathname.startsWith(`${BASE}/store/books/`) || url.pathname.startsWith(`${BASE}/store/audio/`)) return;
  if (request.headers.has("range")) return;

  if (request.mode === "navigate") {
    event.respondWith(networkFirst(request, url));
  } else if (url.pathname.startsWith(`${BASE}/_next/static/`)) {
    event.respondWith(cacheFirst(request));
  } else {
    event.respondWith(staleWhileRevalidate(request));
  }
});
